//! GF(2^8) arithmetic for RAID6 Q-syndrome recovery.
//!
//! The field is generated by x^8 + x^4 + x^3 + x^2 + 1 (0x11d) with the
//! generator {02}: the field md computes Q in (`Q = Σ g^i · D_i`), shared by
//! the common RAID6 controller implementations.

const POLYNOMIAL: u16 = 0x11d;

struct Tables {
    /// `exp[i] = g^i`, repeated once so a product of two logarithms indexes
    /// it without a modulo.
    exp: [u8; 510],
    log: [u8; 256],
}

const TABLES: Tables = build_tables();

const fn build_tables() -> Tables {
    let mut exp = [0u8; 510];
    let mut log = [0u8; 256];
    let mut value: u16 = 1;
    let mut power = 0;
    while power < 255 {
        exp[power] = value as u8;
        exp[power + 255] = value as u8;
        log[value as usize] = power as u8;
        value <<= 1;
        if value & 0x100 != 0 {
            value ^= POLYNOMIAL;
        }
        power += 1;
    }
    Tables { exp, log }
}

/// `g^power` for the generator {02}.
pub(crate) fn pow2(power: usize) -> u8 {
    TABLES.exp[power % 255]
}

pub(crate) fn mul(a: u8, b: u8) -> u8 {
    if a == 0 || b == 0 {
        return 0;
    }
    TABLES.exp[TABLES.log[a as usize] as usize + TABLES.log[b as usize] as usize]
}

/// Multiplicative inverse; `None` for zero, which has none.
pub(crate) fn inverse(a: u8) -> Option<u8> {
    if a == 0 {
        return None;
    }
    Some(TABLES.exp[255 - TABLES.log[a as usize] as usize])
}

/// Products of every byte value with a fixed coefficient, so bulk loops over a
/// chunk cost one table lookup per byte.
pub(crate) fn mul_table(coefficient: u8) -> [u8; 256] {
    let mut table = [0u8; 256];
    for (value, product) in table.iter_mut().enumerate() {
        *product = mul(coefficient, value as u8);
    }
    table
}

/// `target ^= coefficient · source`, byte by byte.
pub(crate) fn mul_xor_into(target: &mut [u8], source: &[u8], coefficient: u8) {
    match coefficient {
        0 => {}
        1 => {
            for (byte, &value) in target.iter_mut().zip(source) {
                *byte ^= value;
            }
        }
        _ => {
            let table = mul_table(coefficient);
            for (byte, &value) in target.iter_mut().zip(source) {
                *byte ^= table[value as usize];
            }
        }
    }
}

/// `target = coefficient · target`, byte by byte.
pub(crate) fn scale(target: &mut [u8], coefficient: u8) {
    if coefficient == 1 {
        return;
    }
    let table = mul_table(coefficient);
    for byte in target {
        *byte = table[*byte as usize];
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generator_powers_match_the_md_field() {
        // Known values of {02}^i in GF(2^8)/0x11d.
        assert_eq!(pow2(0), 0x01);
        assert_eq!(pow2(1), 0x02);
        assert_eq!(pow2(7), 0x80);
        assert_eq!(pow2(8), 0x1d);
        assert_eq!(pow2(9), 0x3a);
        assert_eq!(pow2(255), 0x01);
    }

    #[test]
    fn every_nonzero_element_has_an_inverse() {
        for value in 1..=255u8 {
            let inverse = inverse(value).expect("non-zero inverse");
            assert_eq!(mul(value, inverse), 1, "inverse of {value:#04x}");
        }
        assert_eq!(inverse(0), None);
    }

    #[test]
    fn multiplication_distributes_over_xor() {
        for a in [0x00u8, 0x01, 0x02, 0x53, 0xca, 0xff] {
            for b in [0x00u8, 0x07, 0x8e, 0xff] {
                for c in [0x00u8, 0x11, 0x80] {
                    assert_eq!(mul(a, b ^ c), mul(a, b) ^ mul(a, c));
                }
            }
        }
    }

    #[test]
    fn bulk_helpers_agree_with_scalar_multiplication() {
        let source: Vec<u8> = (0..=255u8).collect();
        let mut target = vec![0x5a; 256];
        mul_xor_into(&mut target, &source, 0x1d);
        for (index, &byte) in target.iter().enumerate() {
            assert_eq!(byte, 0x5a ^ mul(0x1d, index as u8));
        }
        let mut scaled = source.clone();
        scale(&mut scaled, 0x8e);
        for (index, &byte) in scaled.iter().enumerate() {
            assert_eq!(byte, mul(0x8e, index as u8));
        }
    }
}
